/* ============================================
   RESPONSIVE — Tablet
   ============================================ */

@media (max-width: 1024px) {
  .hero-headline {
    font-size: clamp(2rem, 5vw, 3.5rem);
  }

  .about-grid {
    grid-template-columns: 1fr;
    gap: var(--spacing-md);
  }

  .philosophy-section {
    grid-template-columns: 1fr;
    gap: var(--spacing-md);
  }

  .services-grid {
    grid-template-columns: 1fr;
    gap: var(--spacing-lg);
  }

  .clients-grid {
    grid-template-columns: repeat(2, 1fr);
  }

  .media-showcase {
    grid-template-columns: repeat(2, 1fr);
  }

  .media-block:nth-child(3) {
    display: none;
  }
}

/* ============================================
   RESPONSIVE — Mobile
   ============================================ */

@media (max-width: 768px) {
  :root {
    --spacing-lg: 2.5rem;
    --spacing-xl: 3rem;
    --spacing-2xl: 5rem;
  }

  .hamburger {
    display: flex;
  }

  .mobile-nav {
    display: flex;
  }

  .nav-desktop {
    display: none;
  }

  .site-header {
    mix-blend-mode: normal;
    color: var(--color-text);
    padding: 1rem var(--spacing-sm);
    background: var(--color-bg);
  }

  .hero {
    padding: 6rem var(--spacing-sm) var(--spacing-lg);
    min-height: auto;
  }

  .hero-content {
    padding-top: var(--spacing-lg);
  }

  .hero-headline {
    font-size: clamp(1.8rem, 7vw, 2.5rem);
  }

  .media-showcase {
    grid-template-columns: 1fr;
    gap: 1rem;
  }

  .media-block:nth-child(3) {
    display: block;
  }

  .marquee-track span {
    font-size: clamp(1.8rem, 8vw, 2.5rem);
  }

  .about-section {
    padding: var(--spacing-lg) var(--spacing-sm);
  }

  .founder-letter-page {
    padding: 6rem var(--spacing-sm) var(--spacing-lg);
  }

  .letter-headline {
    font-size: clamp(2rem, 8vw, 3rem);
  }

  .clients-grid {
    grid-template-columns: 1fr;
    gap: 2rem;
  }

  .services-page {
    padding: 6rem var(--spacing-sm) var(--spacing-lg);
  }

  .services-grid {
    grid-template-columns: 1fr;
    gap: var(--spacing-lg);
  }

  .contact-heading {
    font-size: clamp(3rem, 18vw, 6rem);
  }

  .contact-links {
    flex-direction: column;
    gap: 1.5rem;
  }

  .footer-inner {
    flex-direction: column;
    gap: 0.5rem;
    text-align: center;
  }
}

/* --- Reduced Motion --- */
@media (prefers-reduced-motion: reduce) {
  .marquee-track {
    animation: none;
  }

  *,
  *::before,
  *::after {
    animation-duration: 0.01ms !important;
    transition-duration: 0.01ms !important;
  }
}

/* ============================================
   Volta Studio — Shared Styles
   ============================================ */

/* --- Google Fonts --- */
@import url('https://fonts.googleapis.com/css2?family=Playfair+Display:ital,wght@0,400;0,500;0,600;0,700;0,800;0,900;1,400;1,500;1,600;1,700&family=Inter:wght@300;400;500;600;700&display=swap');

/* --- CSS Custom Properties --- */
:root {
  --color-bg: #F5F2ED;
  --color-text: #1A1A1A;
  --color-text-secondary: #6B6360;
  --color-accent: #B8956A;
  --color-accent-warm: #C47455;
  --color-border: #E0DBD3;
  --color-overlay: rgba(26, 26, 26, 0.95);
  --color-white: #FFFFFF;

  --font-serif: 'Playfair Display', Georgia, 'Times New Roman', serif;
  --font-sans: 'Inter', -apple-system, BlinkMacSystemFont, 'Segoe UI', Roboto, sans-serif;

  --spacing-xs: 0.5rem;
  --spacing-sm: 1rem;
  --spacing-md: 2rem;
  --spacing-lg: 4rem;
  --spacing-xl: 6rem;
  --spacing-2xl: 10rem;

  --container-max: 1280px;
  --content-narrow: 680px;
}

/* --- Reset --- */
*,
*::before,
*::after {
  margin: 0;
  padding: 0;
  box-sizing: border-box;
}

html {
  font-size: 16px;
  -webkit-font-smoothing: antialiased;
  -moz-osx-font-smoothing: grayscale;
  scroll-behavior: smooth;
}

body {
  font-family: var(--font-sans);
  background-color: var(--color-bg);
  color: var(--color-text);
  line-height: 1.6;
  min-height: 100vh;
}

img {
  max-width: 100%;
  display: block;
}

a {
  color: inherit;
  text-decoration: none;
  transition: color 0.2s ease;
}

a:hover {
  color: var(--color-accent);
}

/* --- Header / Navigation --- */
.site-header {
  position: fixed;
  top: 0;
  left: 0;
  right: 0;
  z-index: 100;
  padding: 1.5rem var(--spacing-md);
  mix-blend-mode: difference;
  color: var(--color-white);
}

.site-header.scrolled,
.site-header.header-dark {
  mix-blend-mode: normal;
  color: var(--color-text);
}

.header-inner {
  max-width: var(--container-max);
  margin: 0 auto;
  display: flex;
  justify-content: space-between;
  align-items: center;
}

.logo {
  font-family: var(--font-serif);
  font-size: 1.25rem;
  font-weight: 700;
  letter-spacing: -0.02em;
}

.logo a {
  color: inherit;
}

/* --- Desktop Navigation --- */
.nav-desktop {
  display: flex;
  gap: 2.5rem;
  list-style: none;
}

.nav-desktop a {
  font-size: 0.875rem;
  font-weight: 500;
  letter-spacing: 0.04em;
  text-transform: uppercase;
  color: inherit;
}

.nav-desktop a::after {
  content: '';
  display: block;
  width: 0;
  height: 1px;
  background: currentColor;
  transition: width 0.3s ease;
}

.nav-desktop a:hover::after {
  width: 100%;
}

/* --- Hamburger Button --- */
.hamburger {
  display: none;
  flex-direction: column;
  justify-content: center;
  align-items: center;
  width: 44px;
  height: 44px;
  background: none;
  border: none;
  cursor: pointer;
  z-index: 200;
  padding: 0;
  position: relative;
}

.hamburger span {
  display: block;
  width: 24px;
  height: 1.5px;
  background: currentColor;
  transition: transform 0.3s ease, opacity 0.3s ease;
  position: absolute;
}

.hamburger span:nth-child(1) {
  transform: translateY(-7px);
}

.hamburger span:nth-child(2) {
  transform: translateY(0);
}

.hamburger span:nth-child(3) {
  transform: translateY(7px);
}

.hamburger.active span:nth-child(1) {
  transform: translateY(0) rotate(45deg);
}

.hamburger.active span:nth-child(2) {
  opacity: 0;
}

.hamburger.active span:nth-child(3) {
  transform: translateY(0) rotate(-45deg);
}

/* --- Mobile Overlay Menu --- */
.mobile-nav {
  display: none;
  position: fixed;
  inset: 0;
  background: var(--color-overlay);
  z-index: 150;
  flex-direction: column;
  justify-content: center;
  align-items: center;
  opacity: 0;
  visibility: hidden;
  transition: opacity 0.4s ease, visibility 0.4s ease;
}

.mobile-nav.active {
  opacity: 1;
  visibility: visible;
}

.mobile-nav ul {
  list-style: none;
  text-align: center;
  display: flex;
  flex-direction: column;
  gap: 2.5rem;
}

.mobile-nav a {
  font-family: var(--font-serif);
  font-size: 2.5rem;
  color: var(--color-bg);
  font-weight: 500;
  letter-spacing: -0.01em;
  transition: opacity 0.3s ease;
}

.mobile-nav a:hover {
  opacity: 0.6;
  color: var(--color-bg);
}

/* --- Main Content --- */
.main-content {
  min-height: 100vh;
}

/* --- Page Container --- */
.page-container {
  max-width: var(--container-max);
  margin: 0 auto;
  padding: 0 var(--spacing-md);
}

/* --- Section Spacing --- */
.section {
  padding: var(--spacing-xl) 0;
}

.section-lg {
  padding: var(--spacing-2xl) 0;
}

/* ============================================
   HOME PAGE
   ============================================ */

/* --- Hero --- */
